// Without arrays: tedious and hard to scale
string enemy1 = "Goblin";
string enemy2 = "Dragon";
string enemy3 = "Knight";

// With an array: clean and scalable
string[] enemies = {"Goblin", "Dragon", "Knight"};
Console.WriteLine(enemies[0]);
Console.WriteLine(enemies[1]);
Console.WriteLine(enemies[2]);

// Empty array: filled with defaults
int[] scores = new int[5];
Console.WriteLine(scores[0]);

// Array with values
string[] weapons = {"Sword", "Bow", "Staff"};
Console.WriteLine(weapons[2]);

// Different types
bool[] achievements = {true, false, true};
double[] health = {100.0, 75.5, 50.0};
char[] grades = {'A', 'B', 'C'};

// Modify an element
scores[0] = 95;
Console.WriteLine(scores[0]);

string[] weapons = {"Sword", "Bow", "Staff"};

// Read values
Console.WriteLine(weapons[0]);
Console.WriteLine(weapons[1]);

// Modify values
weapons[0] = "Great Sword";
Console.WriteLine(weapons[0]);

// Check length
Console.WriteLine(weapons.Length);

// Verify index before accessing
int index = 1;
if (index < weapons.Length)
{
    Console.WriteLine(weapons[index]);
}
else
{
    Console.WriteLine("Index out of bounds");
}

int[] scores = {90, 85, 88, 92, 87};

// For loop: access by index
int sum = 0;
for (int i = 0; i < scores.Length; i++)
{
    sum += scores[i];
}
Console.WriteLine($"Total: {sum}");

// Foreach loop: direct element access
foreach (int score in scores)
{
    Console.WriteLine(score);
}

// Find highest
int highest = scores[0];
foreach (int score in scores)
{
    if (score > highest) highest = score;
}
Console.WriteLine($"Highest: {highest}");

// Create 3x3 grid
int[,] grid = new int[3, 3];

// Set values
grid[0, 0] = 1;
grid[1, 1] = 5;
grid[2, 2] = 9;

// Initialize with values
int[,] board = {
    {1, 2, 3},
    {4, 5, 6},
    {7, 8, 9}
};

// Loop through grid
for (int row = 0; row < 3; row++)
{
    for (int col = 0; col < 3; col++)
    {
        Console.WriteLine($"[{row},{col}] = {board[row, col]}");
    }
}

// Create a list
List<string> inventory = new List<string>();

// Add items
inventory.Add("Sword");
inventory.Add("Shield");
inventory.Add("Potion");
Console.WriteLine($"Items: {inventory.Count}");

// Access by index
Console.WriteLine(inventory[0]);

// Check if item exists
if (inventory.Contains("Sword"))
{
    Console.WriteLine("You have a sword!");
}

// Remove item
inventory.Remove("Potion");
Console.WriteLine($"Items after removal: {inventory.Count}");

// Loop through list
foreach (string item in inventory)
{
    Console.WriteLine(item);
}

List<string> inventory = new List<string> {"Sword", "Shield", "Potion", "Key"};

// Check if item exists
if (inventory.Contains("Key"))
{
    Console.WriteLine("Door unlocked!");
}

// Find position
int pos = inventory.IndexOf("Potion");
if (pos >= 0)
{
    Console.WriteLine($"Potion at position {pos}");
}

// Insert at position
inventory.Insert(0, "Crown");
Console.WriteLine($"First item: {inventory[0]}");

// Remove by position
inventory.RemoveAt(2);

// Show all items
foreach (string item in inventory)
{
    Console.WriteLine(item);
}

// Clear inventory
inventory.Clear();
Console.WriteLine($"Items remaining: {inventory.Count}");

List<string> inventory = new List<string>();
bool playing = true;

while (playing)
{
    Console.WriteLine("\n=== INVENTORY ===" );
    Console.WriteLine($"Items: {inventory.Count}");
    Console.WriteLine("1. View items");
    Console.WriteLine("2. Add item");
    Console.WriteLine("3. Remove item");
    Console.WriteLine("4. Search item");
    Console.WriteLine("5. Exit");
    Console.Write("Choose: ");

    string choice = Console.ReadLine() ?? "";

    if (choice == "1")
    {
        if (inventory.Count == 0)
        {
            Console.WriteLine("Inventory empty.");
        }
        else
        {
            foreach (string item in inventory)
            {
                Console.WriteLine($"- {item}");
            }
        }
    }
    else if (choice == "2")
    {
        Console.Write("Item name: ");
        string item = Console.ReadLine() ?? "";
        if (!string.IsNullOrEmpty(item))
        {
            inventory.Add(item);
            Console.WriteLine("Added!");
        }
    }
    else if (choice == "3")
    {
        Console.Write("Item name to remove: ");
        string item = Console.ReadLine() ?? "";
        if (inventory.Remove(item))
        {
            Console.WriteLine("Removed!");
        }
        else
        {
            Console.WriteLine("Item not found.");
        }
    }
    else if (choice == "4")
    {
        Console.Write("Search for: ");
        string item = Console.ReadLine() ?? "";
        int pos = inventory.IndexOf(item);
        if (pos >= 0)
        {
            Console.WriteLine($"Found at position {pos + 1}");
        }
        else
        {
            Console.WriteLine("Not found.");
        }
    }
    else if (choice == "5")
    {
        playing = false;
    }
}
